using System;
using FairyTales.Cache;
using UnityEngine;

namespace FairyTales.Diagnostics
{
    /// <summary>
    /// Server-side control over narration, piggybacked on the log-mirror config
    /// response. Store review takes days, so anything we might need to fix in a
    /// hurry — a bad narrator voice, audio generated by a broken TTS build — must be
    /// fixable from the backend alone:
    ///
    ///   narrationEpoch        raise it to make every client drop its generated audio
    ///                         and narrate again (pre-recorded downloads are kept)
    ///   defaultNarratorGender the voice for users who never opened the voice panel
    ///
    /// Both are optional: a response without them changes nothing.
    /// </summary>
    public static class NarrationConfig
    {
        private const string PrefEpoch = "ft_narrationEpoch";
        private const string PrefVerbose = "ft_narration_verbose";

        /// <summary>
        /// Per-request narration logging. ON by default so the very first build after
        /// a narration change is diagnosable; the server can switch it off with
        /// "narrationQuiet": true once things are quiet — it costs one POST per page.
        /// </summary>
        public static bool Verbose => PlayerPrefs.GetInt(PrefVerbose, 1) == 1;

        public static void Apply(string json)
        {
            if (string.IsNullOrEmpty(json)) return;
            try
            {
                var cfg = JsonUtility.FromJson<Dto>(json);
                if (cfg == null) return;

                if (!string.IsNullOrEmpty(cfg.defaultNarratorGender))
                    UserProfile.SetNarratorDefault(cfg.defaultNarratorGender);

                // JsonUtility cannot tell an absent bool from false, so the server
                // field is inverted: absent = keep logging, true = go quiet.
                int verbose = cfg.narrationQuiet ? 0 : 1;
                if (PlayerPrefs.GetInt(PrefVerbose, 1) != verbose)
                {
                    PlayerPrefs.SetInt(PrefVerbose, verbose);
                    PlayerPrefs.Save();
                }

                // The config comes back with every log batch, so the reset can land
                // mid-generation. Deleting the folder under a running job would strip
                // pages out of a book that then marks itself complete — leaving silent
                // gaps. Skip this round; the next batch (or launch) applies it.
                if (cfg.narrationEpoch > PlayerPrefs.GetInt(PrefEpoch, 0)
                    && !UI.Narration.NarrationProgressScreen.IsGenerating)
                {
                    AssetCache.ClearGeneratedNarration();
                    PlayerPrefs.SetInt(PrefEpoch, cfg.narrationEpoch);
                    PlayerPrefs.Save();
                    RemoteLog.Event("narration_epoch_reset", $"epoch={cfg.narrationEpoch}");
                }
            }
            catch { /* ignore malformed config */ }
        }

        [Serializable]
        private class Dto
        {
            public int narrationEpoch;
            public string defaultNarratorGender;
            public bool narrationQuiet; // true = stop per-request narration logging
        }
    }
}
